package io.max.hone

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

// Generated from Material Symbols Rounded (Apache License 2.0, Google), weight 600, filled.
// Bold rounded glyphs, close to Nothing OS's own icons; the stock Material Icons only come in one weight.

private fun symbol(name: String, d: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960.toFloat(), 960.toFloat())
        .addPath(PathParser().parsePathString(d).toNodes(), fill = SolidColor(Color.Black))
        .build()

/** Same glyphs as [symbol], straight from the Material Symbols SVGs, whose view box starts at y = -960. */
private fun symbolTop(name: String, d: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960.toFloat(), 960.toFloat())
        .addGroup(translationY = 960f)
        .addPath(PathParser().parsePathString(d).toNodes(), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()

/** Hand-drawn filled glyphs on the same 960 grid; a round-joined outline softens the corners. */
private fun rounded(name: String, fill: String? = null, stroke: String? = null): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f).apply {
        if (fill != null) addPath(
            PathParser().parsePathString(fill).toNodes(), fill = SolidColor(Color.Black),
            stroke = SolidColor(Color.Black), strokeLineWidth = 40f, strokeLineJoin = StrokeJoin.Round,
        )
        if (stroke != null) addPath(
            PathParser().parsePathString(stroke).toNodes(), stroke = SolidColor(Color.Black), strokeLineWidth = 56f,
            strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round,
        )
    }.build()

